D = lambda nn: R_poly(D_poly(nn))(nn)

for nn in range(_sage_const_2 , _sage_const_49 ):
    An = QQ(_sage_const_1024 *(_sage_const_2 *nn+_sage_const_5 )**_sage_const_4 *(_sage_const_2 *nn+_sage_const_7 )**_sage_const_3 *(_sage_const_2 *nn+_sage_const_9 )**_sage_const_3 *(_sage_const_946 *nn**_sage_const_2 +_sage_const_6407 *nn+_sage_const_10860 ))
    Bn = QQ(_sage_const_128 *(_sage_const_2 *nn+_sage_const_7 )**_sage_const_3 *(_sage_const_2 *nn+_sage_const_9 )**_sage_const_3 *(_sage_const_104060 *nn**_sage_const_6 +_sage_const_1745370 *nn**_sage_const_5 +_sage_const_12145238 *nn**_sage_const_4 +_sage_const_44886481 *nn**_sage_const_3 +_sage_const_92943995 *nn**_sage_const_2 +_sage_const_102256019 *nn+_sage_const_46709052 ))
    An1 = QQ(_sage_const_1024 *(_sage_const_2 *(nn-_sage_const_1 )+_sage_const_5 )**_sage_const_4 *(_sage_const_2 *(nn-_sage_const_1 )+_sage_const_7 )**_sage_const_3 *(_sage_const_2 *(nn-_sage_const_1 )+_sage_const_9 )**_sage_const_3 *(_sage_const_946 *(nn-_sage_const_1 )**_sage_const_2 +_sage_const_6407 *(nn-_sage_const_1 )+_sage_const_10860 ))
    Cn1 = QQ(_sage_const_16 *((nn-_sage_const_1 )+_sage_const_3 )**_sage_const_4 *(_sage_const_2 *(nn-_sage_const_1 )+_sage_const_9 )**_sage_const_3 *(_sage_const_3784 *(nn-_sage_const_1 )**_sage_const_5 +_sage_const_57792 *(nn-_sage_const_1 )**_sage_const_4 +_sage_const_351019 *(nn-_sage_const_1 )**_sage_const_3 +_sage_const_1059230 *(nn-_sage_const_1 )**_sage_const_2 +_sage_const_1587211 *(nn-_sage_const_1 )+_sage_const_944620 ))
    An2 = QQ(_sage_const_1024 *(_sage_const_2 *(nn-_sage_const_2 )+_sage_const_5 )**_sage_const_4 *(_sage_const_2 *(nn-_sage_const_2 )+_sage_const_7 )**_sage_const_3 *(_sage_const_2 *(nn-_sage_const_2 )+_sage_const_9 )**_sage_const_3 *(_sage_const_946 *(nn-_sage_const_2 )**_sage_const_2 +_sage_const_6407 *(nn-_sage_const_2 )+_sage_const_10860 ))
    Dn2 = QQ(((nn-_sage_const_2 )+_sage_const_3 )**_sage_const_4 *((nn-_sage_const_2 )+_sage_const_4 )**_sage_const_6 *(_sage_const_946 *(nn-_sage_const_2 )**_sage_const_2 +_sage_const_4515 *(nn-_sage_const_2 )+_sage_const_5399 ))
    q[nn+_sage_const_1 ] = Bn/An * q[nn] - Cn1/An1 * q[nn-_sage_const_1 ] + Dn2/An2 * q[nn-_sage_const_2 ]

